/** Space out groups for the phone page; a lone character keeps its spot. */
const lay = (sc: PicScene): PicScene => ((sc.mo?.length ?? 0) > 1 ? stage(sc) : sc);

export const HABIT_BOOKS: PictureBook[] = RAW.map((b) => ({
  ...b,
  cover: lay(b.cover),
  pages: b.pages.map((pg) => ({ ...pg, scene: lay(pg.scene) })),
}));
